extensions.example:
export function start() {
vue.ar.scale(30)
}
export function update(dt: number) {
if (vue.ar.placed) self.ry += 40 * dt
}

const B = vue.bt
export function start() {
B.run(self, B.sel(
B.seq(B.cond(e => vue.dist(e, 'Player') < 200), B.act(e => { e.vx = (vue.find('Player').x - e.x) > 0 ? 160 : -160; return 'running' })),
B.seq(B.act(e => { e.vx = 0 }), B.wait(1))
))
}

export function start() {
const flock = vue.crowd.add('sheep', { speed: 90 })
vue.crowd.flee(flock, 'Dog', 200)
}

export function start() {
vue.day.setHour(18)
vue.day.speed(120)
}
export function update(dt: number) {
vue.hud('Time', Math.floor(vue.day.hour) + ':00')
}

export function click() {
vue.destruct.explode(self.x, self.y, 120)
}
export function collide(other: any) {
if (other.hasTag('bullet')) vue.destruct.shatter(self, { pieces: 12 })
}

export async function click() {
await vue.dialogue.say('Mira', 'You made it through the forest!')
const pick = await vue.dialogue.ask('Mira', 'Need anything?', ['A map', 'Nothing'])
const line = await vue.dialogue.input('You', 'Ask Mira anything')
await vue.dialogue.say('Mira', await vue.dialogue.chat('Mira', line, 'You are Mira, a cheerful forest guide.'))
}

export function start() {
vue.director.spawner('Zombie', { max: 12, tag: 'zombie', around: 'Player' })
vue.director.onPhase(p => vue.hud('Threat', p))
}
export function collide(other: any) {
if (other.hasTag('zombie')) vue.director.stress(15)
}

export function update(dt: number) {
self.vx = vue.pad.axis('lx') * 240
if (vue.pad.pressed('a')) self.vy = -600
if (vue.pad.pressed('x')) vue.pad.vibrate(150, 0.6)
}

export function update(dt: number) {
if (vue.hands.pinch('right')) {
const p = vue.hands.tip('right', 'index')
if (p) { self.x = p.x; self.y = p.y; self.z = p.z }
}
}

export async function click() {
await vue.voice.say('Welcome, traveler. The gate opens at dawn.', { voice: 'bm_george', entity: self })
}

export function start() {
vue.blur.strength(0.8)
vue.blur.trails(0.4)
}

export async function start() {
const code = await vue.net.host()
vue.hud('Room', code)
vue.net.replicate(self)
vue.net.on('chat', (msg, from) => vue.log(from, msg))
}

export function start() {
vue.every(1, () => vue.nav.go(self, 'Player', 140))
}

export function start() {
vue.fx.emitter('fire', { follow: self, oy: -10 })
}
export function click() {
vue.fx.burst(self.x, self.y, 'explosion')
}

export function start() {
vue.pbr.material(self, { metalness: 1, roughness: 0.2 })
vue.pbr.tag('lava', { emissive: '#ff5a1f', glow: 2 })
}

export function collide(other: any) {
vue.post.flash('#ff3355', 0.25)
vue.post.set({ saturation: 0.4, vignette: 0.6 })
vue.after(1, () => vue.post.set({ saturation: 1.1, vignette: 0.35 }))
}

export function start() {
vue.shadows.range(60)
vue.shadows.softness(6)
}

export function start() {
vue.stream.radius(1800)
}
export function update(dt: number) {
vue.hud('Awake', vue.stream.active)
}

export function start() {
vue.terrain.generate('Ground', { width: 200, seed: 7, caves: 0.4 })
}
// 3D: vue.terrain.generate3({ size: 200, height: 16, seed: 3 })

export function start() {
vue.touch.buttons([{ key: 'space', label: 'Jump' }, { key: 'e', label: 'Use' }])
}

export async function start() {
await vue.vc.start()
}
export function update(dt: number) {
if (vue.pressed('m')) vue.vc.mute(!vue.vc.talking)
}

export function start() {
vue.volume.rays(1)
vue.volume.fog(0.02)
}

export function start() {
vue.follow(self, 6, 1.6)
}
export function update(dt: number) {
const r = vue.xr.controller(1)
if (r && r.trigger > 0.5) vue.emit('fire')
}

// Tag a box or rectangle "water" in the Inspector
export function update(dt: number) {
if (self.wet) vue.hud('Status', 'Swimming')
}

export function start() {
vue.weather.set('storm', 1)
vue.weather.wind(0.4)
vue.after(30, () => vue.weather.set('clear'))
}
